import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Extract recent actions
    recent_len = min(12, n)
    recent_op = [history[i][1] for i in range(n - recent_len, n)]
    recent_me = [history[i][0] for i in range(n - recent_len, n)]
    op = [h[1] for h in history]
    me = [h[0] for h in history]

    opp_c = sum(1 for x in op if x == 'C')
    opp_d = n - opp_c
    opp_rate = opp_c / n

    recent_opp_c = sum(1 for x in recent_op if x == 'C')
    recent_my_c = sum(1 for x in recent_me if x == 'C')
    recent_opp_d = recent_len - recent_opp_c
    recent_my_d = recent_len - recent_my_c

    last_op = op[-1]
    last_me = me[-1]

    # Endgame: last few rounds, defect unless opponent is nearly perfect cooperator
    rounds_left = 100 - n
    if rounds_left <= 0:
        return 'D'

    # Detect sustained defection (always D) - never cooperate against pure D
    if n >= 6 and opp_d == n:
        # Pure defector: mostly defect, rare probe
        if rng.random() < 0.04:
            return 'C'
        return 'D'

    # Detect always cooperation - exploit aggressively
    if n >= 5 and opp_c == n:
        # Against pure C, defect almost always (max payoff 5 per round)
        if rounds_left <= 3:
            return 'D'
        if rng.random() < 0.92:
            return 'D'
        return 'C'

    # Nearly pure cooperator
    if n >= 8 and opp_rate >= 0.9:
        if rounds_left <= 5:
            return 'D'
        if rng.random() < 0.85:
            return 'D'
        return 'C'

    # Endgame exploitation against any cooperative opponent
    if rounds_left <= 2:
        if opp_rate >= 0.85:
            return 'D'
        return 'D'

    if rounds_left <= 6:
        if opp_rate >= 0.6:
            return 'D'
        return 'D'

    # Detect recent sustained defection
    if recent_len >= 4 and recent_opp_d == recent_len:
        if rng.random() < 0.95:
            return 'D'
        return 'C'

    # Very exploitative opponent (mostly D)
    if n >= 5 and opp_rate < 0.2:
        if rng.random() < 0.9:
            return 'D'
        return 'C'

    # Opponent just defected
    if last_op == 'D':
        # Count recent defection streak
        run_d = 0
        for i in range(n - 1, -1, -1):
            if op[i] == 'D':
                run_d += 1
            else:
                break

        # Long defection streak: punish
        if run_d >= 3:
            if rng.random() < 0.85:
                return 'D'
            return 'C'

        # If opponent overall cooperative, forgive single defection
        if opp_rate >= 0.75 and run_d == 1:
            # Forgive, but if we've been defecting too much, defecting back may be needed
            return 'C'

        # Moderate opponent: retaliate
        if opp_rate >= 0.4:
            if rng.random() < 0.15:
                return 'C'
            return 'D'

        # Defect back
        return 'D'

    # Opponent just cooperated
    # Recent opponent cooperation high: cooperate
    if recent_opp_c >= recent_len - 1:
        # If opponent nearly always cooperates, opportunistically defect
        if opp_rate >= 0.85 and rounds_left > 10:
            if rng.random() < 0.35:
                return 'D'
            return 'C'
        return 'C'

    # If opponent recently defected once but current C: encourage cooperation
    if recent_opp_d >= 2:
        # Opponent mixing in defections
        if recent_opp_d * 2 >= recent_len:
            return 'D' if rng.random() < 0.7 else 'C'
        return 'C'

    # Moderate opponent: cooperate with occasional probe
    if opp_rate >= 0.3:
        if rng.random() < 0.08 and rounds_left > 15:
            return 'D'
        return 'C'

    # Default: defect-ish against low-cooperation
    if rng.random() < 0.6:
        return 'D'
    return 'C'
